insert into "articles" ("id", "title", "summary", "content", "image_url", "approved", "likes", "author_id", "created_at", "updated_at") values (3, 'Night Court closes in five', 'Tide Breakers steal the last set and the trophy under the black lights.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A final that would not end"}]},{"type":"paragraph","content":[{"type":"text","text":"Harbor packed the stands for a five-set grind that felt like it belonged in a later season."}]},{"type":"paragraph","content":[{"type":"text","text":"Iris Cho ran the offense until the last rotation, then let Juno Vale close on the pipe."}]},{"type":"paragraph","content":[{"type":"text","text":"Iron Setters had match point twice. They will be back. The desk already has the clip."}]}]}', '/images/s12.png', 1, 18, 'fixture-admin', 1785118200000, 1785118200000), (4, 'Floodlights open with a statement', 'Volt Diggers sweep Sand Kings and book a semi.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The lights stay on"}]},{"type":"paragraph","content":[{"type":"text","text":"Season four''s quarter-finals opened the way the preview said they would: loud, short, and one-sided."}]},{"type":"paragraph","content":[{"type":"text","text":"Uma Reed put up 28 kills. The block held on the second sideout after the timeout."}]},{"type":"paragraph","content":[{"type":"text","text":"Sand Kings never found a sideout run. Volt wait in the last four."}]}]}', '/images/s13.png', 1, 27, 'fixture-admin', 1786066800000, 1786066800000), (5, 'How Night Owls survived Europe', 'Four sets against Polar Tips and a ticket to the last four.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"One more swing"}]},{"type":"paragraph","content":[{"type":"text","text":"Polar Tips stole the second set. Ember Cox put the next two away from the pipe."}]},{"type":"paragraph","content":[{"type":"text","text":"That is the Night Owls season in miniature: late, loud, and a little bit lucky."}]}]}', '/images/s9.png', 1, 11, 'fixture-user', 1786215600000, 1786215600000), (6, 'The libero watch list', 'Four names the desk cannot stop clipping as playoffs start.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hands first"}]},{"type":"paragraph","content":[{"type":"text","text":"Mae Frost is the obvious one. The other three are quieter and maybe more dangerous."}]},{"type":"paragraph","content":[{"type":"text","text":"If you only watch the highlights you will miss the digs that start the points."}]}]}', '/images/s6.png', 1, 9, 'fixture-admin', 1786724400000, 1786724400000), (7, 'Crimson Floor punch through Asia', 'Glass Cannons had the highlight. Crimson Floor had the scoreboard.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ugly and enough"}]},{"type":"paragraph","content":[{"type":"text","text":"Four sets, one timeout that actually worked, and a serve that kept leaking long until it didn''t."}]},{"type":"paragraph","content":[{"type":"text","text":"The other half of the bracket now runs through a team a lot of previews buried."}]}]}', '/images/s5.png', 1, 14, 'fixture-admin', 1786313100000, 1786313100000), (8, 'Playoff week is here', 'The final is set: Volt Diggers against Crimson Floor. Third place is Saturday.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What still matters"}]},{"type":"paragraph","content":[{"type":"text","text":"Both semis are in the book. Volt closed Echo Block in four. Crimson Floor stole the fifth from Night Owls."}]},{"type":"paragraph","content":[{"type":"text","text":"The Floodlights trophy is still on the table. Come back after Sunday."}]}]}', '/images/recGfx.png', 1, 22, 'fixture-admin', 1788274800000, 1788274800000), (9, 'Unsigned notes from the booth', 'A pending desk piece that should not appear on the public list.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This one is still in review and should stay off the homepage."}]}]}', '/images/s3.png', null, 0, 'fixture-user', 1788350400000, 1788350400000);
